Add({
	kind = "figure",
	id = "marshal-dughan",
	title = "Marshal Dughan",
	aliases = { "Dughan" },
	subtitle = "Marshal of Goldshire",
	tier = "B",
	region = "elwynn-forest",
	npc = { 240 },
	allegiance = "Kingdom of Stormwind · Stormwind Army",
