Add({
	kind = "topic",
	id = "camping",
	title = "Camping",
	category = "concept",
	unlock = {
		{ type = "quest", id = 95998 },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Camping is the old art of the road: to build a fire in the wild, to share it, and to rest beside it before the journey goes on. Travellers across {link:azeroth}Azeroth{/link} have always known that a night by a good fire can mean the difference between reaching the next town and never reaching it at all.]=],
		},
		{
			title = "The Fire and the Crafts",
			text = [=[A camp begins with a campfire, built by those who know the art of cooking. Other travellers may then add to it, each according to the craft they know. A smith sets up a sharpening wheel. A leatherworker raises a tent. An alchemist, an enchanter, a miner or a tailor each brings something of their own: a well of mana, an enchanted lute, a lodestone, a banner of their people. The greatest of these works are built from plans kept by the masters of each craft, and some of those plans are said to lie in the hands of dangerous foes.]=],
		},
		{
			title = "The Custom of the Fire",
			text = [=[By custom, each traveller adds a single work to a shared fire, and no craft is set twice beside the same flames. Those who sit a while by such a fire rise from it refreshed, and they carry its benefit with them for hours on the road.]=],
		},
	},
})
